body {
    margin: 0;
    background: #f0f2f5;
}

.policy-suite-app {
    max-width: 1200px;
    margin: 0 auto;
    padding: 24px;
    font-family: "Helvetica Neue", Arial, sans-serif;
    color: #1f2d3d;
}

.app-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 24px;
}

.app-header h1 {
    margin: 0;
    font-size: 24px;
    color: #1f2d3d;
}

.app-subtitle {
    margin: 4px 0 0;
    color: #8a96a3;
    font-size: 14px;
}

.create-button {
    background: #2f6fed;
    color: #fff;
    border: none;
    padding: 10px 18px;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    font-size: 14px;
}

.create-button:hover {
    background: #2559c9;
}

.app-body {
    display: block;
}

.app-body--split {
    display: grid;
    grid-template-columns: 1fr 400px;
    gap: 20px;
    align-items: start;
}

.loading {
    text-align: center;
    padding: 48px;
    font-size: 16px;
    color: #8a96a3;
}

.error-message {
    background: #fdeaea;
    color: #b3261e;
    padding: 12px 16px;
    margin-bottom: 20px;
    border-radius: 6px;
    border-left: 4px solid #b3261e;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.error-message button {
    background: none;
    border: none;
    color: #b3261e;
    cursor: pointer;
    font-weight: 600;
    text-decoration: underline;
}
